<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_once __DIR__.'/validation.php';
function find_user_by_username(string $username): ?array { $s=db()->prepare('SELECT u.*, r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username=? LIMIT 1'); $s->execute([$username]); return $s->fetch() ?: null; }
function find_user_by_email(string $email): ?array { $s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1'); $s->execute([$email]); return $s->fetch() ?: null; }
function create_user(array $d): int { $role=db()->query("SELECT id FROM roles WHERE name='Guest' LIMIT 1")->fetchColumn() ?: 7; $token=bin2hex(random_bytes(32)); $s=db()->prepare('INSERT INTO users(username,password_hash,email,email_verify_token,role_id,madrasa_id,position_id,status) VALUES (?,?,?,?,?,?,?,\'pending\')'); $s->execute([$d['username'],password_hash($d['password'],PASSWORD_DEFAULT),$d['email'],$token,$role,$d['madrasa_id']?:null,$d['position_id']?:null]); $uid=(int)db()->lastInsertId(); $p=db()->prepare('INSERT INTO user_profiles(user_id,full_name,address,place,district,state,country,living_place,working_place,certificate_number,msr_number,phone) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)'); $p->execute([$uid,$d['full_name'],$d['address'],$d['place'],$d['district'],$d['state'],$d['country'],$d['living_place'],$d['working_place'],$d['certificate_number'],$d['msr_number'],$d['phone']??null]); db()->prepare('INSERT INTO email_preferences(user_id) VALUES (?)')->execute([$uid]); audit('registration','users',$uid); return $uid; }
function profile_completion(array $p): int { $fields=['full_name','address','place','district','state','country','living_place','working_place','phone','photo']; $done=0; foreach($fields as $f) if(!empty($p[$f])) $done++; return (int)round($done/count($fields)*100); }
